<details><summary>Here is the code I used on testing</summary>
<p>

```javascript
import {
  Text,
  AppState,
  View,
  StyleSheet,
  Modal,
  TouchableHighlight,
  Button,
  Platform,
} from 'react-native';
import Constants from 'expo-constants';
import * as LocalAuthentication from 'expo-local-authentication';

const styles = StyleSheet.create({
  container: {
    alignContent: 'center',
    flex: 1,
    justifyContent: 'center',
    padding: 8,
    paddingTop: Constants.statusBarHeight,
  },
  innerContainer: {
    alignItems: 'center',
    flex: 1,
    justifyContent: 'center',
    marginTop: '30%',
  },
  modal: {
    alignItems: 'center',
    flex: 1,
    justifyContent: 'center',
    marginTop: '90%',
  },
  text: {
    alignSelf: 'center',
    fontSize: 22,
    paddingTop: 20,
  },
});

export default class LocalAuthTest extends React.Component {
  state = {
    appState: null,
    authenticated: false,
    enrolledLevel: null,
    failedCount: 0,
    modalVisible: false,
  };

  componentDidMount() {
    AppState.addEventListener('change', this.handleAppStateChange);
    this.checkDeviceSecurity();
  }

  componentWillUnmount() {
    AppState.removeEventListener('change', this.handleAppStateChange);
  }

  handleAppStateChange = nextAppState => {
    if (
      this.state.appState &&
      this.state.appState.match(/inactive|background/) &&
      nextAppState === 'active'
    ) {
      this.checkDeviceSecurity();
    }
    this.setState({appState: nextAppState});
  };

  async checkDeviceSecurity() {
    const level = await LocalAuthentication.getEnrolledLevelAsync();
    switch (level) {
      case 0:
        this.setState({enrolledLevel: 'SecurityLevel.NONE'});
        break;
      case 1:
        this.setState({enrolledLevel: 'SecurityLevel.SECRET'});
        break;
      case 2:
        this.setState({enrolledLevel: 'SecurityLevel.BIOMETRIC'});
        break;
    }
  }

  clearState = () => {
    this.setState({authenticated: false, failedCount: 0});
  };

  scanFingerPrint = async () => {
    try {
      const results = await LocalAuthentication.authenticateAsync();
      if (results.success) {
        this.setState({
          authenticated: true,
          failedCount: 0,
        });
      } else {
        this.setState(prev => {
          return {
            failedCount: prev.failedCount + 1,
          };
        });
      }
    } catch (e) {
      console.log(e);

      if (Platform.OS === 'android') {
        await LocalAuthentication.cancelAuthenticate().catch(e => console.log(e));
      }
    }
  };

  render() {
    return (
      <View style={[styles.container, {backgroundColor: 'white'}]}>
        {this.state.enrolledLevel && <Text style={styles.text}>{this.state.enrolledLevel}</Text>}
        <Button
          title={
            this.state.authenticated
              ? 'Reset and begin Authentication again'
              : 'Begin Authentication'
          }
          onPress={() => {
            this.clearState();
            this.scanFingerPrint();
          }}
        />

        {this.state.authenticated && <Text style={styles.text}>Authentication Successful! 🎉</Text>}
      </View>
    );
  }
}
```

